mapper.select:
SELECT ve.*, v.voucher_no, v.voucher_date
FROM voucher_entry ve
JOIN voucher v ON ve.voucher_id = v.id
WHERE ve.account_code = #{accountCode}
AND v.period = #{period}
AND v.status = 'POSTED'
ORDER BY v.voucher_date, v.voucher_no, ve.seq
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM voucher_entry ve
JOIN voucher v ON ve.voucher_id = v.id
WHERE ve.account_code = #{accountCode}
AND v.period = #{period}
AND v.status = 'POSTED'
